-- Existing products remain the sellable records referenced by historical dispatches.
CREATE TABLE product_families(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE product_varieties(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES product_families(id),name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(family_id,name));
ALTER TABLE products ADD COLUMN variety_id TEXT REFERENCES product_varieties(id);
ALTER TABLE products ADD COLUMN packaging TEXT;
ALTER TABLE dispatch_items ADD COLUMN variety_id TEXT;
CREATE INDEX varieties_family_order ON product_varieties(family_id,sort_order,name);
CREATE INDEX products_variety_order ON products(variety_id,sort_order,name);

